\subsection{A Gaussian-to-Gaussian Comparison Lemma}\label{sec: Gaussian vs Gaussian}
The proofs of the main results in this section rely on the following lemma. Let $V$ and $Y$ be centered Gaussian random vectors in $\RR^{p}$
with covariance matrices $\Sigma^{V}$ and
$\Sigma^{Y}$, respectively. The following lemma compares the distribution functions
of $\max_{1 \leq j \leq p}V_{j} \text{and} \max_{1 \leq j \leq p} Y_{j}$
in terms of $p$ and
\begin{equation*}
\Delta_0:=\max_{1\leq j,k\leq p}\left|\Sigma^V_{jk}-\Sigma^Y_{jk}\right|.
\end{equation*}


\begin{lemma}[Comparison of Distributions of Gaussian Maxima]\label{lemma: distances Gaussian to Gaussian}
Suppose that there are some constants $0 < c_{1} < C_{1}$ such that  $c_{1} \leq \Sigma^Y_{jj}\leq C_{1}$ for  all $1\leq j \leq p$.
Then there exists a constant $C>0$ depending only on $c_{1}$ and $C_{1}$ such that
\begin{equation*}
\sup_{t\in\RR}\left|\Pr\left(\max_{1 \leq j \leq p} V_{j}\leq t\right)-\Pr\left(\max_{1 \leq j \leq p} Y_{j}\leq t\right)\right| \leq  C\Delta_{0}^{1/3}(1 \vee \log (p/\Delta_0))^{2/3}.
\end{equation*}
\end{lemma}
